import{_ as r,o as t,c as n,a2 as i}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Symbiose-Arbeitsgesetz","description":"","frontmatter":{},"headers":[],"relativePath":"de/0041-共生劳动法.md","filePath":"de/0041-共生劳动法.md"}'),s={name:"de/0041-共生劳动法.md"};function a(d,e,u,h,g,l){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="symbiose-arbeitsgesetz" tabindex="-1">Symbiose-Arbeitsgesetz <a class="header-anchor" href="#symbiose-arbeitsgesetz" aria-label="Permalink to &quot;Symbiose-Arbeitsgesetz&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>41</td></tr><tr><td>Modul</td><td>Rechtssystem und Governance-Rahmen</td></tr><tr><td>Kernschlüsselwörter</td><td>Symbiose-Arbeit, Mehr-Arbeit-Mehr-Gewinn, Arbeitsrechte, Gemeinsamer Produktionsvertrag, Anti-Ausbeutung</td></tr></tbody></table><h2 id="i-legislatives-ziel-und-grundprinzipien" tabindex="-1">I. Legislatives Ziel und Grundprinzipien <a class="header-anchor" href="#i-legislatives-ziel-und-grundprinzipien" aria-label="Permalink to &quot;I. Legislatives Ziel und Grundprinzipien&quot;">​</a></h2><p>Das 《Symbiose-Arbeitsgesetz》 ist eines der zentralen Gesetze im Rechtssystem der Anker-Symbiose-Zivilisation, parallel zur 《Symbiose-Verfassung》. Es zielt darauf ab, alle Arbeits- und Beitragsaktivitäten innerhalb von Hengyuanzhou zu regulieren, die Verteilungsordnung von &quot;mehr Arbeit mehr Gewinn, autonomes Wachstum&quot; zu etablieren und die Wurzeln der räuberischen Ausbeutung auf rechtlicher Ebene zu beseitigen.</p><p>Dieses Gesetz legt folgende Grundprinzipien fest:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th></tr></thead><tbody><tr><td>Prinzip der Arbeitswürde</td><td>Alle rechtmäßige Arbeit ist gesetzlich geschützt, die persönliche Würde des Arbeitnehmers darf nicht verletzt werden</td></tr><tr><td>Prinzip des Mehr-Arbeit-Mehr-Gewinns</td><td>Die Arbeitsvergütung ist direkt an den Beitragsumfang gebunden, je größer der Beitrag, desto höher der Gewinn, Gewinn ohne Arbeit ist verboten</td></tr><tr><td>Prinzip der freiwilligen Arbeit</td><td>Zwangsarbeit und Sklaverei sind verboten, der Arbeitnehmer hat das Recht, Arbeitsinhalt und Arbeitsweise frei zu wählen</td></tr><tr><td>Prinzip der gerechten Vergütung</td><td>Gleicher Lohn für gleiche Arbeit, Vergütungsdiskriminierung aufgrund von Rasse, Kultivierungsniveau, Herkunft ist verboten</td></tr><tr><td>Prinzip der Arbeitssicherheit</td><td>Staat und Zivilisation sind verpflichtet, den Arbeitnehmern eine sichere Arbeitsumgebung und grundlegende soziale Sicherheit zu bieten</td></tr><tr><td>Prinzip der symbiotischen Zusammenarbeit</td><td>Förderung der Zusammenarbeit und gegenseitigen Hilfe zwischen Arbeitnehmern, Widerspruch gegen bösartigen Wettbewerb und Nullsummenspiele</td></tr></tbody></table><h2 id="ii-grundrechte-der-arbeitnehmer" tabindex="-1">II. Grundrechte der Arbeitnehmer <a class="header-anchor" href="#ii-grundrechte-der-arbeitnehmer" aria-label="Permalink to &quot;II. Grundrechte der Arbeitnehmer&quot;">​</a></h2><p>Das Symbiose-Arbeitsgesetz gewährt allen Wesen mit Arbeitsfähigkeit innerhalb von Hengyuanzhou folgende Rechte:</p><ol><li><strong>Recht auf gleichberechtigte Beschäftigung</strong>: Kein Wesen wird bei der Jobsuche und Einstellung aufgrund von Rasse, Kultivierungsniveau, Herkunft, Geschlecht usw. diskriminiert.</li><li><strong>Recht auf freie Berufswahl</strong>: Der Arbeitnehmer hat das Recht, Beruf, Arbeitsplatz und Arbeitsort nach eigenem Willen und Fähigkeit zu wählen, und hat das Recht, den Beruf gesetzlich zu wechseln.</li><li><strong>Recht auf angemessene Vergütung</strong>: Der Arbeitnehmer hat das Recht, eine seinem Arbeitsbeitrag entsprechende Vergütung zu erhalten, die Vergütung darf nicht unter dem von der Zivilisation festgelegten Mindestsicherheitsstandard liegen.</li><li><strong>Recht auf Ruhe und Urlaub</strong>: Der Arbeitnehmer hat das Recht auf eine angemessene Arbeitszeitgestaltung und regelmäßigen Urlaub, unbegrenzte Verlängerung der Arbeitszeit ist verboten.</li><li><strong>Recht auf Arbeitssicherheit</strong>: Der Arbeitnehmer hat das Recht, in einer sicheren und gesunden Umgebung zu arbeiten, der Arbeitgeber muss arbeitsrechtliche Schutzbedingungen nach Standards bereitstellen.</li><li><strong>Recht auf Berufsausbildung</strong>: Der Arbeitnehmer hat das Recht, berufliche Fähigkeitsausbildung und Kultivierungsanleitung zu erhalten, Arbeitgeber und Staat sind verpflichtet, Ausbildungsressourcen bereitzustellen.</li><li><strong>Recht auf Vereinigung und Verhandlung</strong>: Der Arbeitnehmer hat das Recht, gesetzlich eine Arbeitnehmervereinigung zu gründen oder ihr beizutreten, und hat das Recht, seine Rechte durch Kollektivverhandlungen zu wahren.</li><li><strong>Recht auf Beschwerde und Rechtsbehelf</strong>: Der Arbeitnehmer hat bei Verletzung seiner Arbeitsrechte das Recht, Beschwerde und Klage bei der Arbeits仲裁behörde und dem Symbiose-Gericht einzureichen.</li></ol><h2 id="iii-rechtliche-verankerung-des-mechanismus-des-gemeinsamen-produktionsvertrags" tabindex="-1">III. Rechtliche Verankerung des Mechanismus des gemeinsamen Produktionsvertrags <a class="header-anchor" href="#iii-rechtliche-verankerung-des-mechanismus-des-gemeinsamen-produktionsvertrags" aria-label="Permalink to &quot;III. Rechtliche Verankerung des Mechanismus des gemeinsamen Produktionsvertrags&quot;">​</a></h2><p>Der Mechanismus des gemeinsamen Produktionsvertrags ist das zentrale System der Ressourcenverteilung der Anker-Symbiose-Zivilisation, und das 《Symbiose-Arbeitsgesetz》 verankert es in Rechtsform:</p><ul><li><strong>Vertragssubjekt</strong>: Jedes Wesen mit Arbeitsfähigkeit kann Vertragssubjekt sein, sowohl Einzelpersonen als auch Kollektive können Verträge abschließen.</li><li><strong>Vertragsinhalt</strong>: Umfasst, ist aber nicht beschränkt auf, Entwicklung von Kultivierungsressourcen, Wartung von Ebenen, Wissenstransfer, technologische Forschung und Entwicklung, öffentliche Dienste usw.</li><li><strong>Vertragslaufzeit</strong>: Wird je nach Art des Vertragsinhalts festgelegt, kurzfristige Verträge betragen ein bis drei Jahre, langfristige Verträge fünf bis zwanzig Jahre, nach Ablauf kann verlängert werden.</li><li><strong>Gewinnverteilung</strong>: Der Gewinn des Vertragspartners ist direkt an seine Produktion gebunden, ein Teil der Produktion wird an die öffentliche Reserve abgeführt, der verbleibende Teil gehört dem Vertragspartner.</li><li><strong>Austrittsmechanismus</strong>: Der Vertragspartner hat das Recht, nach vorheriger Ankündigung innerhalb einer angemessenen Frist aus dem Vertrag auszutreten, er darf nicht zwangsweise an das Vertragsverhältnis gebunden werden.</li><li><strong>Streitbeilegung</strong>: Vertragsstreitigkeiten werden vorrangig durch Arbeits仲裁 gelöst, wer mit dem仲裁ergebnis nicht einverstanden ist, kann beim Symbiose-Gericht klagen.</li></ul><h2 id="iv-besonderer-arbeitsschutz" tabindex="-1">IV. Besonderer Arbeitsschutz <a class="header-anchor" href="#iv-besonderer-arbeitsschutz" aria-label="Permalink to &quot;IV. Besonderer Arbeitsschutz&quot;">​</a></h2><p>Um den besonderen Bedürfnissen verschiedener Lebensformen innerhalb von Hengyuanzhou Rechnung zu tragen, legt dieses Gesetz ein System des besonderen Arbeitsschutzes fest:</p><table tabindex="0"><thead><tr><th>Schutzgruppe</th><th>Besondere Schutzmaßnahmen</th></tr></thead><tbody><tr><td>Anfänger-Kultivierer</td><td>Dürfen keine Hochrisikoarbeiten zugewiesen bekommen, die ihre Fähigkeiten übersteigen, müssen mit Mentorenanleitung ausgestattet werden</td></tr><tr><td>Weibliche Wesen in Schwangerschafts- und Wochenbettphase</td><td>Haben Anspruch auf bezahlten Mutterschaftsurlaub von nicht weniger als sechs Monaten, dürfen in der Stillzeit keine Hochintensivarbeiten zugewiesen bekommen</td></tr><tr><td>Behinderte und verletzte/kranke Wesen</td><td>Haben Anspruch auf angemessene Arbeitsplatzanpassung und barrierefreie Arbeitsumgebung</td></tr><tr><td>Arbeitnehmer anderer Rassen</td><td>Der Arbeitgeber muss die physiologischen Merkmale und kulturellen Gewohnheiten anderer Rassen respektieren und angepasste Arbeitsbedingungen bereitstellen</td></tr><tr><td>Ältere Arbeitnehmer</td><td>Können nach Erreichen eines bestimmten Alters eine Reduzierung der Arbeitsintensität oder einen Wechsel zu einer Beratungsposition beantragen</td></tr></tbody></table><h2 id="v-rechtliche-verantwortung-und-durchsetzungsgarantie" tabindex="-1">V. Rechtliche Verantwortung und Durchsetzungsgarantie <a class="header-anchor" href="#v-rechtliche-verantwortung-und-durchsetzungsgarantie" aria-label="Permalink to &quot;V. Rechtliche Verantwortung und Durchsetzungsgarantie&quot;">​</a></h2><p>Arbeitgeber, die gegen die Bestimmungen dieses Gesetzes verstoßen, tragen je nach Schwere des Verstoßes folgende Verantwortung:</p><ol><li>Zahlung der fälligen Vergütung an den Arbeitnehmer sowie Schadenersatz (Schadenersatz beträgt das Ein- bis Dreifache der ausstehenden Vergütung).</li><li>Anordnung zur fristgerechten Behebung, bei Nichtbehebung innerhalb der Frist wird eine Geldbuße verhängt.</li><li>In schweren Fällen wird die Gewerbeerlaubnis entzogen und die verantwortlichen Personen für einen bestimmten Zeitraum von der Ausübung von Verwaltungstätigkeiten ausgeschlossen.</li><li>Bei Straftatbestand wird strafrechtliche Verantwortung gesetzlich verfolgt.</li></ol><p>Der Staat richtet eine Arbeitsaufsichtsbehörde ein, die für die Überwachung und Prüfung der Einhaltung des Arbeitsgesetzes durch die Arbeitgeber verantwortlich ist. Die Arbeitnehmervereinigungen haben das Recht, im Namen der Arbeitnehmer an der Arbeitsaufsicht und Kollektivverhandlungen teilzunehmen.</p><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Das 《Symbiose-Arbeitsgesetz》 ist der rechtliche Träger des Konzepts &quot;mehr Arbeit mehr Gewinn&quot; der Anker-Symbiose-Zivilisation. Es hat die Arbeit von einem Objekt der Ausbeutung zu einem respektierten Recht verwandelt und die Verteilung von räuberischer Aneignung zu beitragsbasierter Vergütung gewandelt, wodurch eine solide Grundlage des Arbeitssystems für den gemeinsamen Fortschritt aller Rassen geschaffen wurde.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Allgemeine Grundsätze der Symbiose-Verfassung)</li><li>06-多劳多得分配原理 (Verteilungsprinzip des Mehr-Arbeit-Mehr-Gewinns)</li><li>22-资源分配联产承包机制 (Mechanismus des gemeinsamen Produktionsvertrags zur Ressourcenverteilung)</li><li>42-消费者保护法 (Verbraucherschutzgesetz)</li></ul>',23)])])}const c=r(s,[["render",a]]);export{o as __pageData,c as default};
